[FormDataFieldEventHandler(formDataFieldStr(CustTable, CustTable, AIBBookTable), FormDataFieldEventType::Modified)]
public static void AIBBookTable_OnModified(FormDataObject _sender, FormDataFieldEventArgs _e)
{
    _sender.dataSource().research(true);
}

[FormDataSourceEventHandler(formDataSourceStr(CustTable, CustTable), FormDataSourceEventType::Activated)]
public static void CustTable_OnActivated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    CustTable custTable = _sender.cursor();
    FormFunctionButtonControl bookButton = _sender.formRun().design().controlName(formControlStr(CustTable, AIBBook));
    if (bookButton)
    {
        bookButton.enabled(custTable.AIBBookTable == 0);
    }
}
